<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { oaApi } from '@/api/oa'
import { canOA, messageOf, useOACommands } from '@/utils/oa'
import type { Reimbursement, ReimbursementFields, Workflow } from '@/types/oa'
const { busy, error, run } = useOACommands()
const rows=ref<Reimbursement[]>([]), selected=ref<Reimbursement|null>(null), workflows=ref<Workflow[]>([]), loading=ref(false), tab=ref<'draft'|'in_review'|'history'>('draft'), creating=ref(false)
const form=reactive<ReimbursementFields>({purpose:'',expense_date:'',category:'交通',amount:'',currency:'CNY',attachment_ids:[]})
const workflowId=ref(''), fileInput=ref<HTMLInputElement>(), notice=ref('')
const labels:Record<string,string>={DRAFT:'草稿',IN_REVIEW:'审批中',PAUSED:'已暂停',APPROVED:'已通过',REJECTED:'已退回',CANCELLED:'已撤回'}
const filtered=computed(()=>rows.value.filter(row=>tab.value==='draft'?['DRAFT','REJECTED','CANCELLED'].includes(row.state):tab.value==='in_review'?['IN_REVIEW','PAUSED'].includes(row.state):['APPROVED','REJECTED','CANCELLED'].includes(row.state)))
const editable=computed(()=>creating.value || !!selected.value?.allowed_actions.includes('edit'))
const valid=computed(()=>!!form.purpose.trim()&&!!form.expense_date&&!!form.category&&/^\d+(\.\d{1,2})?$/.test(form.amount))
const uid=()=>crypto.randomUUID()
function apply(row:Reimbursement){creating.value=false;selected.value=row;Object.assign(form,row.fields);notice.value=''}
async function load(){if(!canOA('reimbursement')){error.value='当前账号没有报销读取权限';return};loading.value=true;try{rows.value=await oaApi.reimbursements();workflows.value=await oaApi.workflows(true,'reimbursement');if(selected.value){const fresh=rows.value.find(row=>row.id===selected.value?.id);if(fresh)apply(await oaApi.reimbursement(fresh.id))}}catch(e){error.value=messageOf(e)}finally{loading.value=false}}
function newDraft(){creating.value=true;selected.value=null;Object.assign(form,{purpose:'',expense_date:'',category:'交通',amount:'',currency:'CNY',attachment_ids:[]});workflowId.value=workflows.value[0]?.id||'';notice.value=''}
async function create(){if(!valid.value||!workflowId.value)return;const result=await run('reimbursement:create',{operation_id:uid(),workflow_definition_id:workflowId.value,fields:{...form}},p=>oaApi.createReimbursement(p));if(result){await load();const row=rows.value.find(item=>item.id===result.result.id);if(row)apply(row)}}
async function save(){if(!selected.value||!valid.value)return;const result=await run('reimbursement:save',{operation_id:uid(),expected_revision:selected.value.revision,fields:{...form}},p=>oaApi.saveReimbursement(selected.value!.id,p));if(result){apply(result.result);await load()}}
async function submit(){if(!selected.value)return;const result=await run('reimbursement:submit',{operation_id:uid(),expected_revision:selected.value.revision,requested_submission_version:selected.value.submission_version+1},p=>oaApi.submitReimbursement(selected.value!.id,p));if(result){apply(result.result);await load()}}
async function command(action:'withdraw'|'archive'){if(!selected.value)return;const result=await run('reimbursement:'+action,{operation_id:uid(),expected_revision:selected.value.revision},p=>action==='withdraw'?oaApi.withdrawReimbursement(selected.value!.id,p):oaApi.archiveReimbursement(selected.value!.id,p));if(result){apply(result.result);await load()}}
async function upload(file:File){if(!selected.value)return;const data=new FormData();data.append('file',file);data.append('operation_id',uid());data.append('expected_revision',String(selected.value.revision));try{const result=await oaApi.uploadReimbursement(selected.value.id,data);notice.value='发票已上传';selected.value={...selected.value,...(result.result as any)};await load()}catch(e){error.value=messageOf(e)}}
function pick(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(file)void upload(file)}
onMounted(load)
</script>
<template><main class="workbench manual-oa reimbursement-page" v-loading="loading"><header class="page-heading"><div><p class="eyebrow">正式 OA · 费用管理</p><h1>报销工作台</h1><p class="muted">填写报销草稿，上传发票，跟踪审批和历史版本。</p></div><div class="actions"><el-button @click="load">刷新</el-button><el-button type="primary" @click="newDraft">新建报销</el-button></div></header><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="notice" :title="notice" type="success" :closable="false"/><div class="oa-two-pane"><section class="oa-section"><div class="actions oa-tabs"><el-button v-for="item in [{key:'draft',label:'报销草稿'},{key:'in_review',label:'审批中'},{key:'history',label:'历史'}]" :key="item.key" :type="tab===item.key?'primary':'default'" @click="tab=item.key as typeof tab">{{item.label}}</el-button></div><el-empty v-if="!filtered.length" description="暂无报销记录"/><button v-for="row in filtered" :key="row.id" class="oa-list-item" :class="{active:selected?.id===row.id}" @click="apply(row)"><strong>{{row.business_no}}</strong><span>{{row.fields.purpose}} · {{row.fields.amount}} 元</span><span>{{labels[row.state]||row.state}} · 修订 {{row.revision}}</span></button></section><section class="oa-section"><el-empty v-if="!selected && !creating" description="选择一笔报销，或新建草稿"/><template v-if="creating || selected"><div v-if="selected" class="node-heading"><h2>{{selected.business_no}}</h2><el-tag>{{labels[selected.state]||selected.state}}</el-tag></div><el-form label-position="top" class="oa-grid"><el-form-item v-if="creating" label="审批流程"><el-select v-model="workflowId" placeholder="选择审批流程"><el-option v-for="workflow in workflows" :key="workflow.id" :label="workflow.name" :value="workflow.id"/></el-select></el-form-item><el-form-item label="报销事由"><el-input v-model="form.purpose" type="textarea" :disabled="!editable"/></el-form-item><el-form-item label="费用日期"><el-date-picker v-model="form.expense_date" type="date" value-format="YYYY-MM-DD" :disabled="!editable"/></el-form-item><el-form-item label="费用类别"><el-select v-model="form.category" :disabled="!editable"><el-option label="交通" value="交通"/><el-option label="差旅" value="差旅"/><el-option label="办公" value="办公"/><el-option label="招待" value="招待"/><el-option label="其他" value="其他"/></el-select></el-form-item><el-form-item label="金额（元）"><el-input v-model="form.amount" :disabled="!editable" placeholder="例如 128.50"/></el-form-item></el-form><div v-if="selected" class="attachment-panel"><h3>发票材料</h3><input ref="fileInput" type="file" accept="image/*,.pdf" :disabled="!editable" @change="pick"/><ul class="attachment-list"><li v-for="item in selected.attachments||[]" :key="item.id||item.attachment_id" class="attachment-row"><span>{{item.filename}}</span><el-tag>{{item.scan_status||item.status||'待校验'}}</el-tag></li></ul></div><div class="actions form-actions"><el-button v-if="creating" type="primary" :disabled="busy||!valid||!workflowId" @click="create">创建报销草稿</el-button><el-button v-if="!creating && editable" :disabled="busy||!valid" @click="save">保存草稿</el-button><el-button v-if="selected && selected.allowed_actions.includes('submit')" type="primary" :disabled="busy||!valid" @click="submit">提交审批</el-button><el-button v-if="selected && selected.allowed_actions.includes('withdraw')" @click="command('withdraw')">撤回</el-button><el-button v-if="selected && selected.allowed_actions.includes('archive')" @click="command('archive')">归档</el-button></div><p v-if="selected" class="muted">提交轮次：{{selected.submission_version}} · 当前修订：{{selected.revision}}</p><el-timeline v-if="selected?.history?.length"><el-timeline-item v-for="(item,index) in selected.history" :key="index">{{item.action||item.state||'流程记录'}} <span class="muted">{{item.created_at||''}}</span></el-timeline-item></el-timeline></template></section></div></main></template>
<style scoped>.reimbursement-page .oa-section{min-width:0}.reimbursement-page .el-form-item{min-width:0}.reimbursement-page .el-date-editor{width:100%}</style>